---RefreshBoardBySkillId 根据道具id刷新提示板
---@param skillId integer @ 道具id
function OverseaManageMenuRecommendTips:RefreshBoardBySkillId(skillId)
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeRecipeSkillVo(skillId)
    for i = 1, #skillVo.skillNum do
        local Txt = self["TextNumber"..i]
        if Txt then
            local addNum = string.split(skillVo.skillNum[i],",")
            local desc = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr3, addNum,nil,skillVo.percentage)
            CfUtils.FillText(Txt,desc)
        end
    end
end


